using DocumentFormat.OpenXml; using DocumentFormat.OpenXml.Packaging; using W=DocumentFormat.OpenXml.Wordprocessing; using Nd30.DocumentEngine.Model; using Nd30.DocumentEngine.Safety;
namespace Nd30.DocumentEngine.Parsing;
public sealed class DocxParser {
 const string Wns="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
 static string Attr(OpenXmlElement? e,string local){if(e is null)return "";foreach(var a in e.GetAttributes())if(a.LocalName==local&&a.NamespaceUri==Wns)return a.Value??"";return "";}
 public ParseResult Parse(string path){var safety=PackageSafetyPreflight.Inspect(path);var diags=new List<Diagnostic>(safety.Diagnostics);if(!safety.IsReadable)return new(null,diags);try{using var d=WordprocessingDocument.Open(path,false);var main=d.MainDocumentPart??throw new InvalidDataException("Missing MainDocumentPart");var body=main.Document.Body??throw new InvalidDataException("Missing body");var paras=body.Elements<W.Paragraph>().Select((p,i)=>P(p,$"p{i+1}")).ToList();var tables=body.Elements<W.Table>().Select((t,i)=>T(t,$"t{i+1}")).ToList();var secs=Sections(main);var heads=main.HeaderParts.Select((h,i)=>new HeaderModel($"h{i+1}",main.GetIdOfPart(h),h.Header.Elements<W.Paragraph>().Select((p,j)=>P(p,$"h{i+1}.p{j+1}")).ToList())).ToList();var foots=main.FooterParts.Select((f,i)=>new FooterModel($"f{i+1}",main.GetIdOfPart(f),f.Footer.Elements<W.Paragraph>().Select((p,j)=>P(p,$"f{i+1}.p{j+1}")).ToList())).ToList();var rel=Relationships(main);var ro=new List<string>();if(main.FootnotesPart!=null)ro.Add("footnotes");if(main.EndnotesPart!=null)ro.Add("endnotes");if(main.WordprocessingCommentsPart!=null)ro.Add("comments");return new(new DocumentModel("doc",paras,tables,secs,heads,foots,Numbering(main),Styles(main),rel,safety,ro),diags);}catch(Exception ex){diags.Add(new("PARSE_ERROR",ex.Message));return new(null,diags);}}
 static ParagraphModel P(W.Paragraph p,string id){var fields=Fields(p,id);var runs=p.Elements<W.Run>().Select((r,i)=>new RunModel($"{id}.r{i+1}",r.InnerText,r.RunProperties?.RunStyle?.Val?.Value,F.Run(r.RunProperties),fields.Where(f=>f.SourceRunIds.Contains($"{id}.r{i+1}")).ToList())).ToList();var np=p.ParagraphProperties?.NumberingProperties;return new(id,p.ParagraphProperties?.ParagraphStyleId?.Val?.Value,np?.NumberingId?.Val?.Value.ToString(),np?.NumberingLevelReference?.Val?.Value,F.Para(p.ParagraphProperties),runs,fields);}
 static IReadOnlyList<FieldModel> Fields(W.Paragraph p,string pid){var result=new List<FieldModel>();int seq=0;var runs=p.Elements<W.Run>().ToList();var active=false;var instr="";var value="";var source=new List<string>();var separated=false;for(int i=0;i<runs.Count;i++){var r=runs[i];var rid=$"{pid}.r{i+1}";foreach(var child in r.ChildElements){if(child is W.FieldChar fc){var t=fc.FieldCharType?.Value;if(t==W.FieldCharValues.Begin){active=true;instr="";value="";source=[];separated=false;}else if(active&&t==W.FieldCharValues.Separate)separated=true;else if(active&&t==W.FieldCharValues.End){result.Add(MakeField($"{pid}.f{++seq}",instr,value,pid,source));active=false;}}else if(active&&child is W.FieldCode code){instr+=code.Text??"";source.Add(rid);}else if(active&&separated&&child is W.Text tx){value+=tx.Text??"";source.Add(rid);}}}
 foreach(var sf in p.Elements<W.SimpleField>()){var ins=sf.Instruction?.Value??"";result.Add(MakeField($"{pid}.f{++seq}",ins,sf.InnerText,pid,[]));}return result;}
 static FieldModel MakeField(string id,string ins,string? val,string pid,IReadOnlyList<string> runs){var normalized=ins.Trim().Split(' ',StringSplitOptions.RemoveEmptyEntries).FirstOrDefault()?.ToUpperInvariant();var type=normalized=="PAGE"?FieldType.Page:normalized=="NUMPAGES"?FieldType.NumPages:FieldType.Unknown;return new(id,ins.Trim(),string.IsNullOrEmpty(val)?null:val,type,pid,runs.Distinct().ToList());}
 static TableModel T(W.Table t,string id)=>new(id,t.Elements<W.TableRow>().Select((r,i)=>new TableRowModel($"{id}.r{i+1}",r.Elements<W.TableCell>().Select((c,j)=>new TableCellModel($"{id}.r{i+1}.c{j+1}",c.Elements<W.Paragraph>().Select((p,k)=>P(p,$"{id}.r{i+1}.c{j+1}.p{k+1}")).ToList())).ToList())).ToList());
 static List<SectionModel> Sections(MainDocumentPart m){var a=new List<SectionModel>();var body=m.Document.Body!;var ps=body.Elements<W.Paragraph>().ToList();for(int n=0;n<ps.Count;n++){var sp=ps[n].ParagraphProperties?.SectionProperties;if(sp!=null)a.Add(S(sp,a.Count+1,$"p{n+1}"));}var finalSect=body.Elements<W.SectionProperties>().LastOrDefault();if(finalSect!=null)a.Add(S(finalSect,a.Count+1,"document-end"));return a;}
 static SectionModel S(W.SectionProperties s,int i,string b){var z=s.GetFirstChild<W.PageSize>();var m=s.GetFirstChild<W.PageMargin>();var pn=s.GetFirstChild<W.PageNumberType>();var orientation=Attr(z,"orient");if(string.IsNullOrWhiteSpace(orientation))orientation="portrait";return new($"s{i}",i,z?.Width?.Value,z?.Height?.Value,orientation,m?.Top?.Value,m?.Right?.Value is null?null:(int?)m.Right.Value,m?.Bottom?.Value,m?.Left?.Value is null?null:(int?)m.Left.Value,s.Elements<W.HeaderReference>().Select(x=>new HeaderFooterReferenceModel(HK(Attr(x,"type")),x.Id?.Value??"")).ToList(),s.Elements<W.FooterReference>().Select(x=>new HeaderFooterReferenceModel(HK(Attr(x,"type")),x.Id?.Value??"")).ToList(),Attr(pn,"fmt"),pn?.Start?.Value,b);}
 static HeaderFooterKind HK(string? x)=>x?.ToLowerInvariant() switch{"first"=>HeaderFooterKind.First,"even"=>HeaderFooterKind.Even,_=>HeaderFooterKind.Default};
 static List<RelationshipModel> Relationships(MainDocumentPart m){var a=new List<RelationshipModel>();foreach(var x in m.Parts){var id=m.GetIdOfPart(x.OpenXmlPart);var target=x.OpenXmlPart.Uri.ToString().TrimStart('/');a.Add(new RelationshipModel(id,x.OpenXmlPart.RelationshipType,target,false,"word/document.xml",target));}foreach(var x in m.ExternalRelationships)a.Add(new RelationshipModel(x.Id,x.RelationshipType,x.Uri.ToString(),true,"word/document.xml",null));foreach(var x in m.HyperlinkRelationships.Where(x=>x.IsExternal))if(!a.Any(y=>y.Id==x.Id))a.Add(new RelationshipModel(x.Id,"http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink",x.Uri.ToString(),true,"word/document.xml",null));return a;}
 static StyleCatalogModel Styles(MainDocumentPart m){var s=m.StyleDefinitionsPart?.Styles;var defaults=new DocumentDefaultsModel(F.Para(s?.DocDefaults?.ParagraphPropertiesDefault?.ParagraphPropertiesBaseStyle),F.Run(s?.DocDefaults?.RunPropertiesDefault?.RunPropertiesBaseStyle));var map=new Dictionary<string,StyleModel>();if(s!=null)foreach(var x in s.Elements<W.Style>()){var id=x.StyleId?.Value;if(string.IsNullOrEmpty(id))continue;var kind=Attr(x,"type").ToLowerInvariant() switch{"paragraph"=>StyleKind.Paragraph,"character"=>StyleKind.Character,"table"=>StyleKind.Table,"numbering"=>StyleKind.Numbering,_=>StyleKind.Unknown};map[id]=new(id,kind,x.BasedOn?.Val?.Value,F.Para(x.StyleParagraphProperties),F.Run(x.StyleRunProperties));}return new(defaults,map);}
 static NumberingCatalogModel Numbering(MainDocumentPart m){var n=m.NumberingDefinitionsPart?.Numbering;if(n is null)return new([],[]);var abs=n.Elements<W.AbstractNum>().Select(a=>new AbstractNumberingModel(a.AbstractNumberId?.Value.ToString()??"",a.Elements<W.Level>().Select(l=>new NumberingLevelModel(l.LevelIndex?.Value??0,Attr(l.NumberingFormat,"val"),l.LevelText?.Val?.Value,l.StartNumberingValue?.Val?.Value)).ToList())).ToList();var inst=n.Elements<W.NumberingInstance>().Select(x=>new NumberingModel(x.NumberID?.Value.ToString()??"",x.AbstractNumId?.Val?.Value.ToString())).ToList();return new(abs,inst);}
 static class F {public static readonly FormattingValues Empty=new(null,null,null,null,null,null,null,null,null,null,null,null,null);static bool? OnOff(W.OnOffType? x)=>x is null?null:(x.Val is null?true:x.Val.Value);public static FormattingValues Run(OpenXmlElement? e){var fonts=e?.GetFirstChild<W.RunFonts>();var sz=e?.GetFirstChild<W.FontSize>();var b=e?.GetFirstChild<W.Bold>();var i=e?.GetFirstChild<W.Italic>();var u=e?.GetFirstChild<W.Underline>();var c=e?.GetFirstChild<W.Color>();return new(fonts?.Ascii?.Value,Half(sz?.Val?.Value),OnOff(b),OnOff(i),u is null?null:!string.Equals(Attr(u,"val"),"none",StringComparison.OrdinalIgnoreCase),c?.Val?.Value,null,null,null,null,null,null,null);}public static FormattingValues Para(OpenXmlElement? e){var j=e?.GetFirstChild<W.Justification>();var sp=e?.GetFirstChild<W.SpacingBetweenLines>();var ind=e?.GetFirstChild<W.Indentation>();return new(null,null,null,null,null,null,Attr(j,"val"),Spacing(sp),Twip(sp?.Before?.Value),Twip(sp?.After?.Value),Twip(ind?.FirstLine?.Value),Twip(ind?.Left?.Value),Twip(ind?.Right?.Value));}static LineSpacingModel? Spacing(W.SpacingBetweenLines? s){var raw=s?.Line?.Value;if(string.IsNullOrWhiteSpace(raw)||!double.TryParse(raw,out var v))return null;var ruleText=Attr(s,"lineRule");var rule=string.Equals(ruleText,"auto",StringComparison.OrdinalIgnoreCase)?LineSpacingRule.Auto:string.Equals(ruleText,"atLeast",StringComparison.OrdinalIgnoreCase)?LineSpacingRule.AtLeast:string.Equals(ruleText,"exact",StringComparison.OrdinalIgnoreCase)?LineSpacingRule.Exact:LineSpacingRule.Unknown;return rule==LineSpacingRule.Auto?new(raw,rule,v/240d,null):rule is LineSpacingRule.AtLeast or LineSpacingRule.Exact?new(raw,rule,null,v/20d):new(raw,rule,null,null);}static double? Half(string? x)=>double.TryParse(x,out var v)?v/2:null;static double? Twip(string? x)=>double.TryParse(x,out var v)?v/20:null;}
}
